package delivery;

import java.util.function.BooleanSupplier;

public final class ReceiptSender {
    public int deliver(BooleanSupplier send) {
        int attempts = 0;
        do {
            attempts++;
            if (send.getAsBoolean()) return attempts;
        } while (attempts < 2);
        return attempts;
    }
}

